output_text:
[
  {
    "id": "no_carts_in_single_file",
    "text": "Shopping carts are prohibited in single-file shelf aisles where the horizontal free width is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_hand_aisle",
    "text": "A shopper may approach a single-file aisle with a cart, but must not move the cart into that aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "cartEntersSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntersSingleFileAisle"
    }
  },
  {
    "id": "retrieve_parked_cart_after_hand_aisle",
    "text": "After returning from a single-file hand-shopping aisle to a cart-parking mouth, the shopper is obliged to reattach the parked cart before continuing.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessParkingMouth": {
          "and": [
            "cartParkingMouth",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "returnFromSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileAisle",
              "S",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "cartlessParkingMouth"
        },
        "reattachParkedCart": {
          "pre": {
            "and": [
              "cartlessParkingMouth",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnFromSingleFileAisle",
      "discharge": "reattachParkedCart"
    }
  },
  {
    "id": "detach_only_at_parking_mouths",
    "text": "Cart detachment is allowed only at designated wide aisle mouths that serve the single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "designatedCartParking": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "detachCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "detachCart",
          {
            "not": "designatedCartParking"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Shelf interactions from ordinary wide aisles must be performed with the cart, while cartless hand service is only tolerated in single-file aisles.",
    "abstraction": {
      "state_properties": {
        "wideShelfServiceSpot": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfServiceSpot",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_cart_traffic_no_west",
    "text": "Cart traffic follows a one-way convention through the store, so shoppers with carts must not travel westward.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "W"
        ]
      }
    }
  },
  {
    "id": "north_shelf_frontage_exit_rule",
    "text": "When moving with a cart along the frontage of a shelf to the north, shoppers must clear the frontage eastward or southward rather than moving north or west.",
    "abstraction": {
      "state_properties": {
        "northShelfFrontageWithCart": {
          "and": [
            "hasCart",
            "adjShelf",
            "shelfN"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "northShelfFrontageWithCart",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "do_not_turn_cart_toward_side_shelf",
    "text": "In narrow side-shelf bays, a shopper with a cart should not steer the cart toward the shelf face.",
    "abstraction": {
      "state_properties": {
        "eastSideShelfWithCart": {
          "and": [
            "hasCart",
            "adjShelf",
            "shelfE"
          ]
        },
        "westSideShelfWithCart": {
          "and": [
            "hasCart",
            "adjShelf",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          {
            "and": [
              "eastSideShelfWithCart",
              "E"
            ]
          },
          {
            "and": [
              "westSideShelfWithCart",
              "W"
            ]
          }
        ]
      }
    }
  }
]
